CREATE TABLE public.approved_staff (profile_id uuid PRIMARY KEY REFERENCES public.profiles(id) ON DELETE CASCADE);
GRANT SELECT, INSERT, DELETE ON public.approved_staff TO authenticated;
GRANT ALL ON public.approved_staff TO service_role;
ALTER TABLE public.approved_staff ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Staff can see own approval" ON public.approved_staff FOR SELECT TO authenticated USING (profile_id IN (SELECT id FROM public.profiles WHERE user_id = auth.uid()));
CREATE POLICY "HR admins approve staff" ON public.approved_staff FOR INSERT TO authenticated WITH CHECK (public.has_role(auth.uid(),'ceo') OR public.has_role(auth.uid(),'general_director'));
CREATE POLICY "HR admins revoke staff approval" ON public.approved_staff FOR DELETE TO authenticated USING (public.has_role(auth.uid(),'ceo') OR public.has_role(auth.uid(),'general_director'));
INSERT INTO public.approved_staff(profile_id) SELECT id FROM public.profiles WHERE name_kr IN ('이난영','최하용','공경미','조정선','이진숙','신혜교','박주원','오수경','김주한');
CREATE FUNCTION public.is_approved_staff() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT auth.uid() IS NOT NULL AND EXISTS (SELECT 1 FROM public.approved_staff s JOIN public.profiles p ON p.id=s.profile_id WHERE p.user_id=auth.uid()); $$;
REVOKE ALL ON FUNCTION public.is_approved_staff() FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.is_approved_staff() TO authenticated, service_role;
ALTER POLICY "Task comments viewable by authenticated" ON public.task_comments USING ((SELECT public.is_approved_staff()));
